from ortools.linear_solver import pywraplp
import json

def main():
    num_students = 40
    num_groups = 8
    students = list(range(1, num_students + 1))
    groups = list(range(1, num_groups + 1))
    skills = ['computational', 'research']

    computational_skill_students = {1, 4, 6, 9, 11, 14, 16, 17, 23, 25, 26, 29, 31, 33, 36, 37}
    research_skill_students = {2, 6, 13, 18, 21, 28, 31, 38}

    has_skill = {}
    for s in skills:
        for i in students:
            if s == 'computational':
                has_skill[(s, i)] = 1 if i in computational_skill_students else 0
            else:
                has_skill[(s, i)] = 1 if i in research_skill_students else 0

    total_computational = sum(1 for i in students if i in computational_skill_students)
    total_research = sum(1 for i in students if i in research_skill_students)
    mean_skill_count = {
        'computational': total_computational / num_groups,
        'research': total_research / num_groups
    }

    solver = pywraplp.Solver.CreateSolver('SCIP')
    if not solver:
        print(json.dumps({
            "student_group_assignment": [1] * num_students,
            "total_skill_imbalance": float('inf')
        }))
        return

    INF = solver.infinity()

    assign = {}
    for i in students:
        for g in groups:
            assign[(i, g)] = solver.BoolVar(f'assign[{i},{g}]')

    group_skill_count = {}
    for s in skills:
        for g in groups:
            group_skill_count[(s, g)] = solver.IntVar(0, num_students, f'group_skill_count[{s},{g}]')

    abs_dev = {}
    for s in skills:
        for g in groups:
            abs_dev[(s, g)] = solver.NumVar(0, INF, f'abs_dev[{s},{g}]')

    for i in students:
        solver.Add(sum(assign[(i, g)] for g in groups) == 1)

    for g in groups:
        solver.Add(sum(assign[(i, g)] for i in students) >= 1)

    for s in skills:
        for g in groups:
            solver.Add(
                group_skill_count[(s, g)] == sum(
                    has_skill[(s, i)] * assign[(i, g)] for i in students
                )
            )

    for s in skills:
        for g in groups:
            solver.Add(
                abs_dev[(s, g)] >= group_skill_count[(s, g)] - mean_skill_count[s]
            )
            solver.Add(
                abs_dev[(s, g)] >= mean_skill_count[s] - group_skill_count[(s, g)]
            )

    objective = solver.Sum(abs_dev[(s, g)] for s in skills for g in groups)
    solver.Minimize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        total_skill_imbalance = solver.Objective().Value()

        assignment_list = [0] * num_students
        for i in students:
            for g in groups:
                if assign[(i, g)].solution_value() > 0.5:
                    assignment_list[i - 1] = g
                    break

        print(json.dumps({
            "student_group_assignment": assignment_list,
            "total_skill_imbalance": total_skill_imbalance
        }))
    else:
        print(json.dumps({
            "student_group_assignment": [1] * num_students,
            "total_skill_imbalance": float('inf')
        }))

if __name__ == '__main__':
    main()
